    ('75000000-0000-0000-0000-000000000039', '11111111-1111-1111-1111-111111111111', '74000000-0000-0000-0000-000000000009', 'PROD-KIT-POST-LASER', 'Kit post laser', 'Kit con gel post laser, protector solar corporal y crema calmante.', 44990, 6, 2, 'Laser Care Demo', '2027-12-31', 'Depilacion laser, depilacion laser rostro, depilacion laser axilas, depilacion laser piernas completas', 'Recomendar despues de laser si no hay irritacion severa.', 'Ofrecer con sesiones laser.', 'No aplicar sobre heridas o reaccion intensa.', true),
    ('75000000-0000-0000-0000-000000000040', '11111111-1111-1111-1111-111111111111', '74000000-0000-0000-0000-000000000010', 'PROD-CREMA-REPARADORA', 'Crema reparadora post tratamiento', 'Crema cosmetica de apoyo posterior a tratamientos superficiales.', 16990, 18, 4, 'Dermocosmetica Demo', '2027-10-31', 'Peeling estetico, microdermoabrasion, dermapen estetico', 'Recomendar solo si el profesional valida uso posterior.', 'Ofrecer con protector solar FPS 50.', 'No usar en heridas abiertas ni alergia conocida.', true),
    ('75000000-0000-0000-0000-000000000041', '11111111-1111-1111-1111-111111111111', '74000000-0000-0000-0000-000000000010', 'PROD-BRUMA-CALMANTE', 'Bruma calmante facial', 'Bruma cosmetica refrescante para rutina facial.', 10990, 18, 4, 'Dermocosmetica Demo', '2027-10-31', 'Limpieza facial profunda, hidratacion facial, microdermoabrasion', 'Recomendar como complemento calmante si no hay alergias.', 'Ofrecer con crema piel sensible.', 'Suspender si genera irritacion.', true),
    ('75000000-0000-0000-0000-000000000042', '11111111-1111-1111-1111-111111111111', '74000000-0000-0000-0000-000000000010', 'PROD-GEL-POST-CERA', 'Gel post depilacion cera', 'Gel calmante cosmetico para despues de depilacion con cera.', 9990, 20, 5, 'Depil Care Demo', '2027-07-31', 'Depilacion con cera, depilacion bozo, depilacion piernas, depilacion bikini', 'Recomendar despues de cera si no hay heridas.', 'Ofrecer con protector solar corporal o facial segun zona.', 'No usar sobre heridas o irritacion intensa.', true),
    ('75000000-0000-0000-0000-000000000043', '11111111-1111-1111-1111-111111111111', '74000000-0000-0000-0000-000000000011', 'PROD-GIFT-25000', 'Gift card $25.000', 'Tarjeta de regalo canjeable en productos o servicios.', 25000, 50, 5, 'Centro Estetico Bella', null, 'Todos los servicios activos', 'Recomendar para regalos de bajo monto.', 'Ofrecer con servicios express.', 'No canjeable por dinero en efectivo.', true),
    ('75000000-0000-0000-0000-000000000044', '11111111-1111-1111-1111-111111111111', '74000000-0000-0000-0000-000000000011', 'PROD-GIFT-100000', 'Gift card $100.000', 'Tarjeta de regalo premium canjeable en servicios o productos.', 100000, 30, 3, 'Centro Estetico Bella', null, 'Todos los servicios activos', 'Recomendar para regalos premium o fechas especiales.', 'Ofrecer con packs promocionales.', 'No canjeable por dinero en efectivo.', true),
    ('75000000-0000-0000-0000-000000000045', '11111111-1111-1111-1111-111111111111', '74000000-0000-0000-0000-000000000011', 'PROD-GIFT-EXPERIENCIA-FACIAL', 'Gift card experiencia facial', 'Tarjeta de regalo para experiencia facial segun disponibilidad.', 69990, 20, 3, 'Centro Estetico Bella', null, 'Limpieza facial profunda, hidratacion facial, rejuvenecimiento facial no invasivo', 'Recomendar para regalos de experiencia.', 'Ofrecer con kit facial.', 'Sujeta a disponibilidad de agenda y evaluacion si aplica.', true),
    ('75000000-0000-0000-0000-000000000046', '11111111-1111-1111-1111-111111111111', '74000000-0000-0000-0000-000000000012', 'PROD-PACK-HIDRATACION-FACIAL', 'Pack hidratacion facial + serum', 'Pack de hidratacion facial y serum acido hialuronico.', 45990, 8, 2, 'Centro Estetico Bella', '2027-12-31', 'Hidratacion facial', 'Recomendar a clientes con necesidad de hidratacion no sensible.', 'Incluye servicio y producto.', 'Sujeto a disponibilidad de agenda y stock.', true),
    ('75000000-0000-0000-0000-000000000047', '11111111-1111-1111-1111-111111111111', '74000000-0000-0000-0000-000000000012', 'PROD-PACK-CORPORAL-RELAX', 'Pack masaje relajante + aceite', 'Pack de masaje relajante y aceite corporal.', 40990, 10, 2, 'Centro Estetico Bella', '2027-12-31', 'Masaje relajante', 'Recomendar para clientes que buscan relajacion.', 'Incluye servicio y aceite corporal.', 'No aplica si hay contraindicaciones de masaje.', true),
    ('75000000-0000-0000-0000-000000000048', '11111111-1111-1111-1111-111111111111', '74000000-0000-0000-0000-000000000012', 'PROD-PACK-CEJAS-MIRADA', 'Pack cejas y mirada', 'Pack de diseno de cejas, tinte de cejas y lifting de pestanas segun disponibilidad.', 54990, 7, 2, 'Centro Estetico Bella', '2027-12-31', 'Diseno de cejas, tinte de cejas, lifting de pestanas', 'Recomendar para clientes que buscan realce de mirada.', 'Ofrecer con aceite cuticulas no aplica; priorizar productos compatibles faciales.', 'Validar alergia ocular o a tintes.', true),
    ('75000000-0000-0000-0000-000000000049', '11111111-1111-1111-1111-111111111111', '74000000-0000-0000-0000-000000000012', 'PROD-PACK-CAPILAR-COLOR', 'Pack color capilar + cuidado', 'Pack para servicio de color y productos de cuidado capilar.', 99990, 6, 2, 'Centro Estetico Bella', '2027-12-31', 'Tintura, balayage, tratamiento capilar', 'Recomendar despues de evaluacion capilar.', 'Incluye shampoo y mascarilla capilar.', 'Sujeto a evaluacion de cabello y stock.', true),
    ('75000000-0000-0000-0000-000000000050', '11111111-1111-1111-1111-111111111111', '74000000-0000-0000-0000-000000000012', 'PROD-PACK-NOVIA', 'Pack novia maquillaje + prueba', 'Pack de prueba de maquillaje novia y maquillaje novia.', 109990, 5, 1, 'Centro Estetico Bella', '2027-12-31', 'Maquillaje novia, prueba maquillaje novia', 'Recomendar para novias con fecha definida.', 'Ofrecer con gift card experiencia facial.', 'Requiere agenda y coordinacion previa.', true)
