insert into aesthetic_business_rule (id, business_id, code, name, rule_type, description, priority, active, rule_payload)
values
    ('76000000-0000-0000-0000-000000000023', '11111111-1111-1111-1111-111111111111', 'IA_RESPONDER_CON_CATALOGO', 'Respuesta IA usando catalogo interno', 'AI_RESPONSE', 'La IA debe responder precios, duraciones, stock, cuidados y contraindicaciones solo desde catalogo interno cargado.', 3, true, '{"catalogRequired":true,"forbidExternalAssumptions":true}'::jsonb),
    ('76000000-0000-0000-0000-000000000024', '11111111-1111-1111-1111-111111111111', 'IA_PRECIO_SERVICIO_EXACTO', 'Precio de servicio exacto', 'AI_RESPONSE', 'Ante consulta de precio, responder valor base configurado y aclarar si disponibilidad o evaluacion quedan pendientes.', 4, true, '{"intent":"consultar_precio_servicio","source":"aesthetic_service.price_base"}'::jsonb),
    ('76000000-0000-0000-0000-000000000025', '11111111-1111-1111-1111-111111111111', 'IA_DURACION_SERVICIO_EXACTA', 'Duracion de servicio exacta', 'AI_RESPONSE', 'Ante consulta de duracion, responder duracion configurada en minutos y no inventar tiempos adicionales.', 5, true, '{"intent":"consultar_duracion_servicio","source":"aesthetic_service.duration_minutes"}'::jsonb),
    ('76000000-0000-0000-0000-000000000026', '11111111-1111-1111-1111-111111111111', 'IA_STOCK_PRODUCTO_EXACTO', 'Stock de producto exacto', 'AI_RESPONSE', 'Ante consulta de producto, responder precio, stock y restricciones desde catalogo.', 6, true, '{"intent":"consultar_productos","source":"aesthetic_product"}'::jsonb),
    ('76000000-0000-0000-0000-000000000027', '11111111-1111-1111-1111-111111111111', 'IA_CUIDADOS_POSTERIORES', 'Cuidados posteriores configurados', 'AI_RESPONSE', 'Ante consulta post tratamiento, responder recomendaciones configuradas del servicio y derivar si hay reaccion adversa.', 7, true, '{"intent":"solicitar_cuidados_posteriores","source":"aesthetic_service.aftercare_recommendations"}'::jsonb),
    ('76000000-0000-0000-0000-000000000028', '11111111-1111-1111-1111-111111111111', 'IA_CONTRAINDICACIONES', 'Contraindicaciones configuradas', 'SAFETY', 'Ante consulta de contraindicaciones, mostrar informacion configurada y recomendar evaluacion profesional si aplica al cliente.', 8, true, '{"intent":"consultar_contraindicaciones","requiresHumanReviewWhenPersonal":true}'::jsonb),
    ('76000000-0000-0000-0000-000000000029', '11111111-1111-1111-1111-111111111111', 'IA_AMBIGUEDAD_PEDIR_ACLARACION', 'Ambiguedad requiere aclaracion', 'AI_RESPONSE', 'Si no se identifica servicio, producto, fecha o necesidad suficiente, pedir aclaracion con opciones concretas.', 9, true, '{"askClarifyingQuestion":true,"showOptions":true}'::jsonb),
    ('76000000-0000-0000-0000-000000000030', '11111111-1111-1111-1111-111111111111', 'IA_DERIVACION_RIESGO', 'Derivacion por riesgo estetico', 'SAFETY', 'Derivar si se mencionan embarazo, alergias, medicamentos, enfermedades, heridas, infeccion, dolor fuerte o procedimiento invasivo.', 4, true, '{"keywords":["embarazo","alergia","medicamento","enfermedad","herida","infeccion","dolor fuerte","procedimiento invasivo"],"handoff":true}'::jsonb),
    ('76000000-0000-0000-0000-000000000031', '11111111-1111-1111-1111-111111111111', 'CATALOGO_SERVICIOS_COMPLETO', 'Catalogo de servicios completo', 'CATALOG', 'El catalogo debe mantener servicios activos por categoria: facial, corporal, depilacion, manicure, pedicure, pestanas, cejas, peluqueria, maquillaje y medicina no invasiva.', 15, true, '{"categories":["FACIAL","CORPORAL","DEPILACION","MANICURE_PEDICURE","PESTANAS_CEJAS","PELUQUERIA","MAQUILLAJE","MEDICINA_NO_INVASIVA"]}'::jsonb),
    ('76000000-0000-0000-0000-000000000032', '11111111-1111-1111-1111-111111111111', 'CATALOGO_PRODUCTOS_COMPLETO', 'Catalogo de productos completo', 'CATALOG', 'El catalogo debe mantener productos por categoria con precio, stock, proveedor, vencimiento, compatibilidad, recomendacion, venta cruzada y restricciones.', 16, true, '{"requiresPrice":true,"requiresStock":true,"requiresCompatibility":true,"requiresRestrictions":true}'::jsonb),
    ('76000000-0000-0000-0000-000000000033', '11111111-1111-1111-1111-111111111111', 'RECOMENDAR_POR_SERVICIO', 'Recomendar productos por servicio', 'RECOMMENDATION', 'Al consultar productos asociados a un tratamiento, recomendar solo productos cuyo campo de compatibilidad incluya el servicio.', 81, true, '{"useField":"compatible_services","validateRestrictions":true}'::jsonb),
    ('76000000-0000-0000-0000-000000000034', '11111111-1111-1111-1111-111111111111', 'RECOMENDAR_POR_NECESIDAD', 'Recomendar por necesidad declarada', 'RECOMMENDATION', 'Si el cliente indica piel seca, piel grasa, manchas, relajacion, color capilar o unas, sugerir categoria relacionada y pedir datos faltantes.', 82, true, '{"needs":["piel seca","piel grasa","manchas","relajacion","color capilar","unas"],"askMissingData":true}'::jsonb),
    ('76000000-0000-0000-0000-000000000035', '11111111-1111-1111-1111-111111111111', 'AGENDA_NO_CONFIRMAR_SIN_BD', 'No confirmar agenda sin base', 'AVAILABILITY', 'La IA puede orientar, pero no debe confirmar reserva sin consultar agenda, profesional, cabina y bloqueo horario.', 17, true, '{"mustCheckBookingTable":true,"mustCheckProfessional":true,"mustCheckRoomOrEquipment":true}'::jsonb),
    ('76000000-0000-0000-0000-000000000036', '11111111-1111-1111-1111-111111111111', 'PAGO_NO_CONFIRMAR_SIN_CONFIG', 'Medios de pago configurados', 'PAYMENT', 'La IA no debe confirmar medios de pago no configurados. Debe consultar configuracion comercial vigente.', 131, true, '{"mustCheckPaymentSettings":true}'::jsonb),
    ('76000000-0000-0000-0000-000000000037', '11111111-1111-1111-1111-111111111111', 'PROMOCION_VALIDAR_CONDICIONES', 'Promocion valida condiciones', 'COMMERCIAL', 'Antes de aplicar promocion validar vigencia, stock, servicio, combinacion y no acumulabilidad.', 91, true, '{"checkValidity":true,"checkStock":true,"notStackableByDefault":true}'::jsonb),
    ('76000000-0000-0000-0000-000000000038', '11111111-1111-1111-1111-111111111111', 'LASER_CUIDADO_SOL', 'Laser requiere cuidado solar', 'SAFETY', 'Para depilacion laser, informar no exposicion solar y uso de protector solar; derivar si hay fotosensibilidad.', 61, true, '{"services":["DEP-LASER","DEP-LASER-ROSTRO","DEP-LASER-AXILAS","DEP-LASER-PIERNAS"],"handoffKeywords":["fotosensible","medicamento","quemadura","embarazo"]}'::jsonb),
    ('76000000-0000-0000-0000-000000000039', '11111111-1111-1111-1111-111111111111', 'PEELING_NO_ACTIVOS_IRRITANTES', 'Peeling sin activos irritantes posteriores', 'SAFETY', 'Despues de peeling o microdermoabrasion no recomendar exfoliantes, retinol ni acidos sin evaluacion profesional.', 62, true, '{"blockedProducts":["PROD-EXFOLIANTE-SUAVE","PROD-EXFOLIANTE-ENZIMATICO","PROD-SERUM-RETINOL-SUAVE"]}'::jsonb),
    ('76000000-0000-0000-0000-000000000040', '11111111-1111-1111-1111-111111111111', 'UNAS_DERIVAR_INFECCION', 'Unas con infeccion se derivan', 'SAFETY', 'Si hay dolor, hongos, infeccion, inflamacion o heridas en unas, no confirmar manicure o pedicure automaticamente.', 63, true, '{"keywords":["hongo","hongos","infeccion","dolor","inflamacion","herida"],"handoff":true}'::jsonb),
    ('76000000-0000-0000-0000-000000000041', '11111111-1111-1111-1111-111111111111', 'CEJAS_PESTANAS_ALERGIA', 'Cejas y pestanas validan alergia', 'SAFETY', 'Para tinte, lifting o extension, preguntar alergias, irritacion ocular o cirugia reciente antes de confirmar.', 64, true, '{"services":["PC-TINTE-CEJAS","PC-LIFTING-PESTANAS","PC-EXTENSION-PESTANAS"],"askAllergy":true}'::jsonb),
    ('76000000-0000-0000-0000-000000000042', '11111111-1111-1111-1111-111111111111', 'CAPILAR_VALIDAR_ALERGIA', 'Color y alisado validan alergia', 'SAFETY', 'Para tintura, balayage y alisado validar alergia, embarazo, cuero cabelludo lesionado y estado del cabello.', 65, true, '{"services":["PEL-TINTURA","PEL-BALAYAGE","PEL-ALISADO"],"askSensitivity":true}'::jsonb),
    ('76000000-0000-0000-0000-000000000043', '11111111-1111-1111-1111-111111111111', 'RESPUESTA_TONO_CORDIAL', 'Tono profesional y cordial', 'AI_RESPONSE', 'Todas las respuestas deben ser claras, profesionales, cordiales, breves y orientadas a siguiente paso.', 200, true, '{"tone":"professional_friendly","maxRecommendedParagraphs":3}'::jsonb),
    ('76000000-0000-0000-0000-000000000044', '11111111-1111-1111-1111-111111111111', 'AUDITORIA_INTENCION', 'Auditoria de intencion', 'AI_RESPONSE', 'Cada analisis debe registrar mensaje, intencion, confianza, entidades, respuesta sugerida, modelo y derivacion.', 201, true, '{"storeIntentLog":true}'::jsonb)
on conflict (business_id, code) do update set
    name = excluded.name,
    rule_type = excluded.rule_type,
    description = excluded.description,
    priority = excluded.priority,
